-- 109: Blackbeard's Roller Coaster (107) came from the Peter Piper Pizza in Las
-- Vegas as "Dragon", 2001-2009 (Carter, 2026-10-31, RCDB page + coords). The
-- site's existing "Peter Piper Pizza" is the Dallas one (32.74, -96.84) whose
-- Dragon Keltan logged - a different ride - so Las Vegas is its own park,
-- "Peter Piper Pizza - Las Vegas" (dash, like the Fun Spot locations).
-- Dragon: Miler oval family coaster, indoor, 2001-2009, linked to Blackbeard's
-- Roller Coaster as the same ride (home = Blackbeard's). Safe to run twice.
INSERT INTO parks (name, lat, lon, region) SELECT 'Peter Piper Pizza - Las Vegas', 36.1650, -115.2087, 'Nevada, US' WHERE NOT EXISTS (SELECT 1 FROM parks WHERE name = 'Peter Piper Pizza - Las Vegas');
INSERT INTO coasters (id, name, park, type, manu, model, h, s, l, inv, dur, yr, opened, openedPrec, closed, closedPrec, laps) SELECT (SELECT COALESCE(MAX(id),0)+1 FROM coasters), 'Dragon', 'Peter Piper Pizza - Las Vegas', 'Steel', 'E&F Miler Industries', 'Miler Family Coaster', NULL, NULL, NULL, 0, NULL, 2001, '2001', 'year', '2009', 'year', 1 WHERE NOT EXISTS (SELECT 1 FROM coasters WHERE name = 'Dragon' AND park = 'Peter Piper Pizza - Las Vegas');
INSERT INTO activity (at, actor, kind, subject, n, detail) SELECT strftime('%Y-%m-%dT%H:%M:%fZ','now'), NULL, 'coaster_added', c.name, NULL, json_object('id', c.id, 'park', c.park) FROM coasters c WHERE c.name = 'Dragon' AND c.park = 'Peter Piper Pizza - Las Vegas' AND NOT EXISTS (SELECT 1 FROM activity a WHERE a.kind = 'coaster_added' AND json_extract(a.detail, '$.id') = c.id);
INSERT OR IGNORE INTO same_ride (coaster, ride) SELECT c.id, h.id FROM coasters c, coasters h WHERE h.name = 'Roller Coaster' AND h.park = 'Blackbeard''s Family Entertainment Center' AND (c.id = h.id OR (c.name = 'Dragon' AND c.park = 'Peter Piper Pizza - Las Vegas'));
INSERT INTO activity (at, actor, kind, subject, n, detail) SELECT strftime('%Y-%m-%dT%H:%M:%fZ','now'), NULL, 'same_ride_set', h.name, (SELECT COUNT(*) FROM same_ride s WHERE s.ride = h.id), json_object('ride', h.id, 'at', (SELECT json_group_array(json_object('id', c.id, 'park', c.park, 'name', c.name)) FROM coasters c JOIN same_ride s ON s.coaster = c.id WHERE s.ride = h.id), 'via', '109') FROM coasters h WHERE h.name = 'Roller Coaster' AND h.park = 'Blackbeard''s Family Entertainment Center' AND (SELECT COUNT(*) FROM same_ride s WHERE s.ride = h.id) > 1 AND NOT EXISTS (SELECT 1 FROM activity a WHERE a.kind = 'same_ride_set' AND a.detail LIKE '%"via":"109"%');
